// Dimensiona o resistor e verifica a potência dissipada.
double calculateLedResistor(double supplyVoltage, double ledForwardVoltage, double ledCurrent) {
    return (supplyVoltage - ledForwardVoltage) / ledCurrent;
}

double calculateResistorPower(double resistorValue, double ledCurrent) {
    return resistorValue * ledCurrent * ledCurrent;
}
